mapper.select:
select u.user_id, u.sip_id,u.dept_id, u.nick_name,u.user_type,u.user_name, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, u.remark,u.result,u.approver,u.approval_time,u.birthday,u.identification_card,u.wechat,u.native_place,u.address,u.card_is,u.card_the,u.shackup_card, u.electronic_signature,u.assist_group,d.dept_name, d.leader from sys_user u
left join sys_dept d on u.dept_id = d.dept_id
where u.del_flag = '0'

	AND u.user_id = #{userId}


	AND u.user_name like concat('%', #{userName}, '%')


	AND u.nick_name like concat('%', #{nickName}, '%')


	AND u.status = #{status}


	AND u.phonenumber like concat('%', #{phonenumber}, '%')


	AND date_format(u.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


	AND date_format(u.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')


	AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE find_in_set(#{deptId}, ancestors) ))


	AND user_type = #{userType}



	${params.dataScope}

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status, u.create_time from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
${params.dataScope}

mapper.update:
update sys_user
dept_id = #{deptId}, user_name = #{userName}, user_type = #{userType}, nick_name = #{nickName}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, result=#{result}, approver=#{approver}, approval_time=#{approvalTime}, birthday=#{birthday}, identification_card=#{identificationCard}, wechat=#{wechat}, native_place=#{nativePlace}, address=#{address}, card_is=#{cardIs}, card_the=#{cardThe}, shackup_card=#{shackupCard}, electronic_signature=#{electronicSignature}, sip_id=#{sipId}, assist_group=#{assistGroup}, update_time = sysdate()
where user_id = #{userId}
